export function ForwardAppendToJson(v: P.ForwardAppend): J {
  return {
    context: v.context,
    epoch: v.epoch.toString(),
    leader_id: v.leaderId.toString(),
    system: v.system,
    condition: (v.condition === undefined ? null : ConditionToJson(v.condition)),
    events: v.events.map(recordToJson),
  };
}

export function ForwardAppendFromJson(j: J): P.ForwardAppend {
  return {
    context: String(j.context),
    epoch: BigInt(j.epoch),
    leaderId: BigInt(j.leader_id),
    system: Boolean(j.system),
    condition: (j.condition === null || j.condition === undefined ? undefined : ConditionFromJson(j.condition)),
    events: (j.events as unknown[]).map(recordFromJson),
  };
}

